use std::process::ExitCode;

use callisto_model::format::{Changeset, PreState};
use callisto_model::{InitReport, MatrixReport, ReleaseReceiptV1, SnapshotReport, StatusReport, VersionReport};
use schemars::schema_for;

use crate::cli::{GlobalArgs, SchemaArgs, SchemaReportType};
use crate::error::CliError;
use crate::output::write_stdout;

pub fn handle(args: SchemaArgs, _global: &GlobalArgs) -> Result<ExitCode, CliError> {
    let schema = match args.target_type.unwrap_or_default() {
        SchemaReportType::Status => schema_for!(StatusReport),
        SchemaReportType::Version => schema_for!(VersionReport),
        SchemaReportType::Snapshot => schema_for!(SnapshotReport),
        SchemaReportType::Init => schema_for!(InitReport),
        SchemaReportType::Changeset => schema_for!(Changeset),
        SchemaReportType::PreState => schema_for!(PreState),
        SchemaReportType::Matrix => schema_for!(MatrixReport),
        SchemaReportType::ReleaseReceipt => schema_for!(ReleaseReceiptV1),
    };

    // A `schemars::Schema` is a plain JSON tree of strings, numbers, and nested maps;
    // it always serializes.
    let json = serde_json::to_string_pretty(&schema).expect("schema serializes");
    write_stdout(format!("{json}\n").as_bytes())?;
    Ok(ExitCode::SUCCESS)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn global() -> GlobalArgs {
        GlobalArgs {
            format: crate::cli::OutputFormat::Text,
            cwd: std::path::PathBuf::from("."),
            dry_run: false,
        }
    }

    /// Every registry entry actually produces a schema; an unknown `--type`
    /// value is rejected earlier, at clap parse time (see `cli.rs`'s
    /// `schema_type_rejects_unknown_value_as_a_usage_error`), so this
    /// handler-level test only needs to cover the exhaustive match's arms.
    #[test]
    fn handle_succeeds_for_every_registered_type() {
        for target_type in [
            SchemaReportType::Status,
            SchemaReportType::Version,
            SchemaReportType::Snapshot,
            SchemaReportType::Init,
            SchemaReportType::Changeset,
            SchemaReportType::PreState,
            SchemaReportType::Matrix,
            SchemaReportType::ReleaseReceipt,
        ] {
            let result = handle(
                SchemaArgs {
                    target_type: Some(target_type),
                },
                &global(),
            );
            assert!(result.is_ok(), "target_type={target_type:?}");
        }
    }
}
use crate::{Version, VersionGrammar};
use indexmap::IndexMap;
use schemars::JsonSchema;
use serde::{Deserialize, Serialize};

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase")]
pub struct PreState {
    pub mode: PreMode,
    pub tag: String,
    #[schemars(with = "std::collections::BTreeMap<String, Version>")]
    pub initial_versions: IndexMap<String, Version>,
    pub changesets: Vec<String>,
}

impl PreState {
    pub fn entering(tag: impl Into<String>, initial_versions: impl IntoIterator<Item = (String, Version)>) -> Self {
        let mut map = IndexMap::new();
        for (pkg, ver) in initial_versions {
            map.entry(pkg).or_insert(ver);
        }
        PreState {
            mode: PreMode::Pre,
            tag: tag.into(),
            initial_versions: map,
            changesets: Vec::new(),
        }
    }

    pub fn exiting(mut self) -> Self {
        self.mode = PreMode::Exit;
        self
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "lowercase")]
pub enum PreMode {
    Pre,
    Exit,
}

pub fn parse_pre_json(input: &str) -> Result<PreState, PreJsonError> {
    let clean_input = input.strip_prefix('\u{FEFF}').unwrap_or(input);
    let val: serde_json::Value =
        serde_json::from_str(clean_input).map_err(|e| PreJsonError::Malformed { message: e.to_string() })?;

    let obj = val.as_object().ok_or_else(|| PreJsonError::Malformed {
        message: "expected a JSON object".to_string(),
    })?;

    let mode_val = obj.get("mode").ok_or(PreJsonError::MissingField { field: "mode" })?;
    let mode_str = mode_val
        .as_str()
        .ok_or(PreJsonError::WrongFieldType { field: "mode" })?;
    let mode = match mode_str {
        "pre" => PreMode::Pre,
        "exit" => PreMode::Exit,
        _ => {
            return Err(PreJsonError::InvalidMode {
                found: mode_str.to_string(),
            })
        }
    };

    let tag_val = obj.get("tag").ok_or(PreJsonError::MissingField { field: "tag" })?;
    let tag = tag_val
        .as_str()
        .ok_or(PreJsonError::WrongFieldType { field: "tag" })?
        .to_string();

    let init_val = obj.get("initialVersions").ok_or(PreJsonError::MissingField {
        field: "initialVersions",
    })?;
    let init_obj = init_val.as_object().ok_or(PreJsonError::WrongFieldType {
        field: "initialVersions",
    })?;

    let mut initial_versions = IndexMap::new();
    for (pkg, v_val) in init_obj {
        let v_str = v_val.as_str().ok_or(PreJsonError::WrongFieldType {
            field: "initialVersions",
        })?;
        let ver = Version::parse(v_str, VersionGrammar::SemVer)
            .or_else(|_| Version::parse(v_str, VersionGrammar::Pep440))
            .map_err(|source| PreJsonError::InvalidInitialVersion {
                package: pkg.clone(),
                raw: v_str.to_string(),
                source,
            })?;
        initial_versions.insert(pkg.clone(), ver);
    }

    let cs_val = obj
        .get("changesets")
        .ok_or(PreJsonError::MissingField { field: "changesets" })?;
    let cs_arr = cs_val
        .as_array()
        .ok_or(PreJsonError::WrongFieldType { field: "changesets" })?;

    let mut changesets = Vec::new();
    for (index, c_val) in cs_arr.iter().enumerate() {
        let c_str = c_val.as_str().ok_or(PreJsonError::InvalidChangesetId { index })?;
        changesets.push(c_str.to_string());
    }

    Ok(PreState {
        mode,
        tag,
        initial_versions,
        changesets,
    })
}

pub fn write_pre_json(state: &PreState) -> String {
    render_pre_json(state, "  ")
}

/// Renders `state`, then reapplies `existing`'s on-disk formatting (BOM, CRLF vs LF, indent width) instead of the
/// default 2-space bare-LF shape, so a CRLF or custom-indent `pre.json` (e.g. `core.autocrlf=true`, or hand-edited)
/// is not reformatted on a `pre exit` or mid-cycle `version` rewrite.
pub fn write_pre_json_preserving(state: &PreState, existing: &str) -> String {
    let fp = PreJsonFingerprint::detect(existing);
    let rendered = render_pre_json(state, &fp.indent_str());
    fp.apply(&rendered)
}

fn render_pre_json(state: &PreState, indent_str: &str) -> String {
    let mut map = IndexMap::new();
    map.insert("mode".to_string(), serde_json::to_value(state.mode).unwrap());
    map.insert("tag".to_string(), serde_json::to_value(&state.tag).unwrap());

    let mut init_map = IndexMap::new();
    for (pkg, ver) in &state.initial_versions {
        init_map.insert(pkg.clone(), serde_json::to_value(ver).unwrap());
    }
    map.insert("initialVersions".to_string(), serde_json::to_value(init_map).unwrap());
    map.insert(
        "changesets".to_string(),
        serde_json::to_value(&state.changesets).unwrap(),
    );

    let formatter = serde_json::ser::PrettyFormatter::with_indent(indent_str.as_bytes());
    let mut buf = Vec::new();
    let mut serializer = serde_json::Serializer::with_formatter(&mut buf, formatter);
    serde::Serialize::serialize(&map, &mut serializer).unwrap();
    let mut out = String::from_utf8(buf).unwrap();
    out.push('\n');
    out
}

/// Byte-level formatting facts (BOM, CRLF, indent) `pre.json` must preserve across a rewrite.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct PreJsonFingerprint {
    has_bom: bool,
    crlf: bool,
    indent: PreJsonIndent,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum PreJsonIndent {
    Spaces(u8),
    Tabs,
}

impl PreJsonFingerprint {
    fn detect(content: &str) -> Self {
        let has_bom = content.starts_with('\u{FEFF}');
        let clean = content.strip_prefix('\u{FEFF}').unwrap_or(content);
        let crlf = clean.contains("\r\n");

        // The first quote-leading line is a top-level key at indent depth 1; its leading whitespace is one unit.
        let mut indent = PreJsonIndent::Spaces(2);
        for line in clean.lines() {
            let trimmed = line.trim_start();
            if trimmed.starts_with('"') && line.len() > trimmed.len() {
                let leading = &line[..line.len() - trimmed.len()];
                indent = if leading.contains('\t') {
                    PreJsonIndent::Tabs
                } else {
                    PreJsonIndent::Spaces(leading.len() as u8)
                };
                break;
            }
        }

        PreJsonFingerprint { has_bom, crlf, indent }
    }

    fn indent_str(&self) -> String {
        match self.indent {
            PreJsonIndent::Tabs => "\t".to_string(),
            PreJsonIndent::Spaces(n) => " ".repeat(n as usize),
        }
    }

    /// Reapplies this fingerprint to `rendered`, a freshly-serialized body with bare-LF endings and no BOM.
    fn apply(&self, rendered: &str) -> String {
        let mut out = if self.crlf {
            rendered.replace("\r\n", "\n").replace('\n', "\r\n")
        } else {
            rendered.to_string()
        };
        if self.has_bom {
            out = format!("\u{FEFF}{out}");
        }
        out
    }
}

#[derive(Debug, thiserror::Error, Clone, PartialEq, Eq)]
#[non_exhaustive]
pub enum PreJsonError {
    #[error("pre.json is not a valid JSON object: {message}")]
    Malformed { message: String },

    #[error("pre.json is missing required field {field:?}")]
    MissingField { field: &'static str },

    #[error("pre.json field {field:?} has the wrong type")]
    WrongFieldType { field: &'static str },

    #[error("pre.json has mode {found:?}, expected \"pre\" or \"exit\"")]
    InvalidMode { found: String },

    #[error("pre.json initialVersions[{package:?}] = {raw:?} is not a valid version: {source}")]
    InvalidInitialVersion {
        package: String,
        raw: String,
        #[source]
        source: crate::VersionParseError,
    },

    #[error("pre.json changesets[{index}] is not a string")]
    InvalidChangesetId { index: usize },
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn pre_json_round_trips() {
        let json = r#"{
  "mode": "pre",
  "tag": "next",
  "initialVersions": {
    "foo": "1.0.0"
  },
  "changesets": [
    "cool-dragons-fly"
  ]
}
"#;
        let state = parse_pre_json(json).unwrap();
        assert_eq!(state.tag, "next");
        let written = write_pre_json(&state);
        assert_eq!(written, json);
    }

    #[test]
    fn pre_json_accepts_pep440_initial_versions() {
        // pre.json files from Python/PyPI workspaces store PEP 440 version
        // strings (e.g. "0.3.2a1") in initialVersions. parse_pre_json must
        // accept them; rejecting them would make pre-mode unusable for Python
        // packages entirely.
        let json = r#"{
  "mode": "pre",
  "tag": "beta",
  "initialVersions": {
    "my-python-pkg": "0.3.2a1"
  },
  "changesets": []
}
"#;
        let state = parse_pre_json(json).unwrap();
        assert_eq!(state.initial_versions["my-python-pkg"].raw(), "0.3.2a1");
    }

    #[test]
    fn pre_json_round_trips_pep440_version() {
        // The PEP 440 initial version string must survive a write → parse cycle
        // unchanged so that pre.json files are idempotent.
        let state = PreState::entering(
            "beta",
            [("pkg".to_string(), {
                crate::Version::parse("1.0.0a1", crate::VersionGrammar::Pep440).unwrap()
            })],
        );
        let written = write_pre_json(&state);
        let reparsed = parse_pre_json(&written).unwrap();
        assert_eq!(reparsed.initial_versions["pkg"].raw(), "1.0.0a1");
    }

    /// `PreState::exiting()` is the only public way out of pre-release mode
    /// -- previously untested end to end. Proves the mode flips to `Exit`
    /// and that this survives a real write -> parse round trip, matching
    /// `pre_json_round_trips`'s style for the "pre" mode above.
    #[test]
    fn pre_state_exiting_flips_mode_and_round_trips_as_exit() {
        let state = PreState::entering(
            "next",
            [(
                "foo".to_string(),
                Version::parse("1.0.0", VersionGrammar::SemVer).unwrap(),
            )],
        );
        assert_eq!(state.mode, PreMode::Pre);

        let exited = state.exiting();
        assert_eq!(exited.mode, PreMode::Exit);

        let written = write_pre_json(&exited);
        assert!(
            written.contains("\"mode\": \"exit\""),
            "written pre.json must serialize mode as \"exit\", got:\n{written}"
        );

        let reparsed = parse_pre_json(&written).unwrap();
        assert_eq!(reparsed.mode, PreMode::Exit);
    }

    #[test]
    fn parse_pre_json_rejects_non_object_json() {
        let err = parse_pre_json("[1, 2, 3]").unwrap_err();
        assert!(
            matches!(err, PreJsonError::Malformed { ref message } if message == "expected a JSON object"),
            "expected Malformed{{\"expected a JSON object\"}}, got {err:?}"
        );
    }

    #[test]
    fn parse_pre_json_rejects_unrecognized_mode_string() {
        let json = r#"{"mode": "paused", "tag": "next", "initialVersions": {}, "changesets": []}"#;
        let err = parse_pre_json(json).unwrap_err();
        assert!(
            matches!(err, PreJsonError::InvalidMode { ref found } if found == "paused"),
            "expected InvalidMode{{\"paused\"}}, got {err:?}"
        );
    }

    #[test]
    fn parse_pre_json_rejects_initial_version_that_is_neither_semver_nor_pep440() {
        let json = r#"{"mode": "pre", "tag": "next", "initialVersions": {"pkg": "not-a-version"}, "changesets": []}"#;
        let err = parse_pre_json(json).unwrap_err();
        assert!(
            matches!(err, PreJsonError::InvalidInitialVersion { ref package, ref raw, .. } if package == "pkg" && raw == "not-a-version"),
            "expected InvalidInitialVersion{{package: \"pkg\", raw: \"not-a-version\"}}, got {err:?}"
        );
    }

    /// Spec: rewriting a CRLF `pre.json` must keep CRLF, the same fingerprinting contract as the manifest editors.
    #[test]
    fn write_pre_json_preserving_keeps_crlf() {
        let existing = "{\r\n  \"mode\": \"pre\",\r\n  \"tag\": \"beta\",\r\n  \"initialVersions\": {},\r\n  \"changesets\": []\r\n}\r\n";
        let state = parse_pre_json(existing).unwrap();

        let rewritten = write_pre_json_preserving(&state, existing);

        assert!(
            rewritten.contains("\r\n"),
            "expected CRLF preserved, got: {rewritten:?}"
        );
        assert!(
            !rewritten.replace("\r\n", "").contains('\n'),
            "no bare LF should remain: {rewritten:?}"
        );
    }

    /// Spec: a tab-indented `pre.json` must be rewritten with tabs, not the default 2-space indent.
    #[test]
    fn write_pre_json_preserving_keeps_tab_indent() {
        let existing =
            "{\n\t\"mode\": \"pre\",\n\t\"tag\": \"beta\",\n\t\"initialVersions\": {},\n\t\"changesets\": []\n}\n";
        let state = parse_pre_json(existing).unwrap();

        let rewritten = write_pre_json_preserving(&state, existing);

        assert!(
            rewritten.lines().any(|l| l.starts_with('\t')),
            "expected tab indent preserved, got: {rewritten:?}"
        );
    }

    /// Spec: a BOM-prefixed `pre.json` must be rewritten with the BOM kept.
    #[test]
    fn write_pre_json_preserving_keeps_bom() {
        let existing =
            "\u{FEFF}{\n  \"mode\": \"pre\",\n  \"tag\": \"beta\",\n  \"initialVersions\": {},\n  \"changesets\": []\n}\n";
        let state = parse_pre_json(existing).unwrap();

        let rewritten = write_pre_json_preserving(&state, existing);

        assert!(
            rewritten.starts_with('\u{FEFF}'),
            "expected BOM preserved, got: {rewritten:?}"
        );
        // The BOM-stripped body must still parse back to the same state.
        let reparsed = parse_pre_json(&rewritten).unwrap();
        assert_eq!(reparsed, state);
    }
}
mod frontmatter;
#[cfg(test)]
mod tests;

use crate::{Severity, SeverityParseError};
use frontmatter::{needs_quoting, parse_entry_line, LineError};

/// One parsed `.changeset/*.md` file: a frontmatter block of
/// `name: severity` entries, followed by a free-text summary.
///
/// Deliberately does not carry a filename or path — this crate is filesystem-free; a caller
/// that reads files off disk attaches the filename itself for sort ordering and error
/// context.
use schemars::JsonSchema;

/// One parsed `.changeset/*.md` file: a frontmatter block of
/// `name: severity` entries, followed by a free-text summary.
///
/// Deliberately does not carry a filename or path — this crate is filesystem-free; a caller
/// that reads files off disk attaches the filename itself for sort ordering and error
/// context.
#[derive(Clone, Debug, PartialEq, Eq, JsonSchema)]
pub struct Changeset {
    pub entries: Vec<Entry>,
    pub summary: String,
}

/// One `"name": severity` frontmatter line, after quote resolution.
///
/// `name` is the raw string as written in the changeset — resolving it to a `PackageId`
/// (bare vs. `ecosystem/name`-prefixed) is a workspace-aware operation this crate cannot
/// perform and does not attempt.
#[derive(Clone, Debug, PartialEq, Eq, JsonSchema)]
pub struct Entry {
    pub name: String,
    pub severity: Severity,
}

impl Changeset {
    /// Convenience wrapper around [`write_changeset`].
    pub fn to_markdown(&self) -> Result<String, WriteError> {
        write_changeset(self)
    }
}

#[derive(Debug, thiserror::Error, miette::Diagnostic, Clone, PartialEq, Eq)]
#[non_exhaustive]
pub enum ParseError {
    /// The file does not open with a `---` delimiter on line 1 at all.
    #[error("changeset does not start with a `---` frontmatter delimiter on line 1")]
    #[diagnostic(
        code(E040),
        help("Add a `---` frontmatter delimiter on line 1 of the changeset file.")
    )]
    MissingFrontmatterStart,

    /// A `---` opened on line 1 but no matching closing `---` line was ever found.
    #[error("frontmatter opened with `---` on line 1 but was never closed with a matching `---`")]
    #[diagnostic(code(E041), help("Ensure frontmatter block closes with `---`."))]
    UnclosedFrontmatter,

    /// A quoted name's opening `"` has no matching closing `"` on the same line.
    #[error("line {line}: quoted name is never closed with a matching `\"`")]
    #[diagnostic(code(E042))]
    UnclosedQuotedName { line: usize },

    /// The closing `"` of a quoted name is not immediately followed by the separator `:`.
    #[error("line {line}: quoted name `{raw}` is followed by unexpected content before the `:` separator")]
    #[diagnostic(code(E043))]
    AmbiguousNameQuoting { line: usize, raw: String },

    /// A bare (unquoted) line contains no `:` at all.
    #[error("line {line}: no `:` separator found in {raw:?}")]
    #[diagnostic(code(E044))]
    MissingSeparator { line: usize, raw: String },

    /// The name resolved to the empty string.
    #[error("line {line}: package name is empty")]
    #[diagnostic(code(E045))]
    EmptyName { line: usize },

    /// The severity token is not one of `major | minor | patch | none` (case-insensitive).
    #[error("line {line}: invalid severity for package {name:?}: {source}")]
    #[diagnostic(code(E046))]
    InvalidSeverity {
        line: usize,
        name: String,
        #[source]
        source: SeverityParseError,
    },

    /// The same (raw, pre-`PackageId`-resolution) name appears twice in one changeset's
    /// frontmatter.
    #[error("line {line}: package {name:?} is named more than once in this changeset's frontmatter (first on line {first_line})")]
    #[diagnostic(code(E047))]
    DuplicateEntry {
        line: usize,
        first_line: usize,
        name: String,
    },

    /// A changeset with one or more entries must have a non-empty summary.
    #[error("changeset has entries but an empty or whitespace-only summary")]
    #[diagnostic(code(E055), help("Add a non-empty summary after the closing `---` delimiter."))]
    EmptySummary,
}

#[derive(Debug, thiserror::Error, miette::Diagnostic, Clone, PartialEq, Eq)]
#[non_exhaustive]
pub enum WriteError {
    /// A changeset with one or more entries must have a non-empty summary.
    #[error("cannot write changeset: entries present but summary is empty or whitespace-only")]
    #[diagnostic(code(E056), help("Provide a non-empty summary describing the change."))]
    EmptySummary,

    /// `entries[index]`'s name is the empty string.
    #[error("entry {index} has an empty package name")]
    #[diagnostic(code(E057))]
    EmptyName { index: usize },

    /// `entries[index]`'s name contains a literal `"`, which cannot be written — no escaping
    /// convention is defined for this grammar.
    #[error("entry {index} name {name:?} contains a literal `\"`, which cannot be written (no escaping convention is defined for this grammar)")]
    #[diagnostic(
        code(E268),
        help("Remove the literal `\"` from the package name before writing the changeset.")
    )]
    NameContainsQuote { index: usize, name: String },
}

/// Parses one `.changeset/*.md` file's contents.
///
/// Grammar: a `---`-delimited frontmatter block starting on line 1, each non-blank,
/// non-comment line inside it shaped `<name>: <severity>`, followed by the file's remaining
/// content as `summary` (trimmed). `#`-comment lines and blank lines inside the frontmatter
/// block are skipped. CRLF line endings are normalized to LF before parsing.
pub fn parse_changeset(source: &str) -> Result<Changeset, ParseError> {
    let trimmed_bom = source.strip_prefix('\u{FEFF}').unwrap_or(source);
    let normalized = trimmed_bom.replace("\r\n", "\n").replace('\r', "\n");
    let lines: Vec<&str> = normalized.split('\n').collect();

    if lines.first().map(|l| l.trim_end()) != Some("---") {
        return Err(ParseError::MissingFrontmatterStart);
    }

    // Two-pass, deliberately: find the frontmatter's boundaries FIRST, then parse content
    // within them. A single pass that tries to parse every line as an entry until it
    // happens to hit a literal "---" cannot tell "this entry is malformed" apart from "the
    // frontmatter was never closed at all" — the first non-entry-shaped line after a missing
    // closing delimiter would otherwise surface as a misleading parse error on that line
    // instead of `UnclosedFrontmatter`.
    let closing_index = lines[1..].iter().position(|&l| l.trim_end() == "---").map(|i| i + 1);
    let Some(closing_index) = closing_index else {
        return Err(ParseError::UnclosedFrontmatter);
    };

    let mut entries: Vec<Entry> = Vec::new();
    let mut first_seen: std::collections::HashMap<String, usize> = std::collections::HashMap::new();

    for (offset, &line) in lines[1..closing_index].iter().enumerate() {
        let line_no = offset + 2; // absolute, 1-indexed; line 1 was "---"
        if line.trim().is_empty() || line.trim_start().starts_with('#') {
            continue;
        }
        let entry = parse_entry_line(line).map_err(|e| promote_line_error(e, line_no))?;
        if let Some(&first_line) = first_seen.get(&entry.name) {
            return Err(ParseError::DuplicateEntry {
                line: line_no,
                first_line,
                name: entry.name,
            });
        }
        first_seen.insert(entry.name.clone(), line_no);
        entries.push(entry);
    }

    let summary = lines[closing_index + 1..].join("\n").trim().to_string();

    // No entries and no summary is a valid empty changeset (the shape `@changesets/cli add
    // --empty` writes) -- entries and an empty summary is still rejected below.
    if !entries.is_empty() && summary.is_empty() {
        return Err(ParseError::EmptySummary);
    }

    Ok(Changeset { entries, summary })
}

fn promote_line_error(err: LineError, line: usize) -> ParseError {
    match err {
        LineError::UnclosedQuotedName => ParseError::UnclosedQuotedName { line },
        LineError::AmbiguousNameQuoting { raw } => ParseError::AmbiguousNameQuoting { line, raw },
        LineError::MissingSeparator { raw } => ParseError::MissingSeparator { line, raw },
        LineError::EmptyName => ParseError::EmptyName { line },
        LineError::InvalidSeverity { name, source } => ParseError::InvalidSeverity { line, name, source },
    }
}

/// Serializes a [`Changeset`] back to `.changeset/*.md` bytes.
///
/// Names are quoted only when necessary. Severities are always written lowercase. Output
/// always uses `\n` line endings and ends with a single trailing newline after the summary.
/// An empty changeset (no entries, no summary) writes as `---\n---\n\n`.
pub fn write_changeset(changeset: &Changeset) -> Result<String, WriteError> {
    if changeset.summary.trim().is_empty() && !changeset.entries.is_empty() {
        return Err(WriteError::EmptySummary);
    }
    for (index, entry) in changeset.entries.iter().enumerate() {
        if entry.name.is_empty() {
            return Err(WriteError::EmptyName { index });
        }
        if entry.name.contains('"') {
            return Err(WriteError::NameContainsQuote {
                index,
                name: entry.name.clone(),
            });
        }
    }

    let mut out = String::from("---\n");
    for entry in &changeset.entries {
        if needs_quoting(&entry.name) {
            out.push_str(&format!("\"{}\": {}\n", entry.name, entry.severity));
        } else {
            out.push_str(&format!("{}: {}\n", entry.name, entry.severity));
        }
    }
    out.push_str("---\n");
    let summary = changeset.summary.trim();
    if !summary.is_empty() {
        out.push('\n');
        out.push_str(summary);
    }
    out.push('\n');
    Ok(out)
}

