    51	fn assert_schema_accepts(schema: &Value, payload: &Value) {
    52	    let validator = jsonschema::validator_for(schema).expect("published schema must compile");
    53	    let errors: Vec<_> = validator.iter_errors(payload).map(|error| error.to_string()).collect();
    54	    assert!(
    55	        errors.is_empty(),
    56	        "schema rejected serialized payload {payload}: {errors:?}"
    57	    );
    58	}
    59	
    60	fn assert_nested_mutations_rejected(schema: &Value, payload: &Value, mutations: &[(&str, Value)]) {
    61	    assert_schema_accepts(schema, payload);
    62	    let validator = jsonschema::validator_for(schema).expect("published schema must compile");
    63	    for (pointer, replacement) in mutations {
    64	        let mut invalid = payload.clone();
    65	        *invalid
    66	            .pointer_mut(pointer)
    67	            .unwrap_or_else(|| panic!("mutation must reach an existing nested value at {pointer}")) = replacement.clone();
    68	        assert!(
    69	            !validator.is_valid(&invalid),
    70	            "schema accepted invalid nested value at {pointer}: {invalid}"
    71	        );
    72	    }
    73	}
