   304	fn receipt() -> ReleaseReceiptV1 {
   305	    let package = ReleasePackageId::parse("cargo/widget-core").unwrap();
   306	    let version = Version::semver(1, 3, 0);
   307	    let revision = CommitSha::parse(&"a".repeat(40)).unwrap();
   308	    let registry = RegistryBindingId::new("cratesIo", RegistryBindingDigest::parse(&"b".repeat(64)).unwrap()).unwrap();
   309	    let publish = ReleaseOperation::registry_publish(package.clone(), version.clone(), registry, vec![]).unwrap();
   310	    let tag = ReleaseOperation::tag(package.clone(), version.clone(), vec![publish.id().clone()]).unwrap();
   311	    let decision = ReleaseDecisionV1::new(vec![ReleaseDecisionEntry {
   312	        package: package.clone(),
   313	        target_version: version.clone(),
   314	        reasons: vec![ReleaseInclusionReason::Changeset],
   315	    }])
   316	    .unwrap();
   317	    let snapshot = ReleaseInputSnapshotV1::new(
   318	        SourceIdentity::GitCommit { sha: revision.clone() },
   319	        vec![ReleasePackageInputV1 {
   320	            package,
   321	            fingerprint: SemanticInputDigest::parse(&"c".repeat(64)).unwrap(),
   322	        }],
   323	    )
   324	    .unwrap();
   325	    let intent = ReleaseIntentV1::new(
   326	        decision,
   327	        snapshot,
   328	        ExecutionTrustProfileV1::GitCommit,
   329	        vec![publish.clone(), tag.clone()],
   330	        vec![],
   331	    )
   332	    .unwrap();
   333	    let envelope = ReleaseRunEnvelopeV1::new(revision.clone(), &intent, None).unwrap();
   334	    let mut state = ReleaseExecutionStateV1::new(&intent, envelope).unwrap();
   335	    for (operation, evidence) in [
   336	        (
   337	            publish,
   338	            ProviderEvidenceV1::RegistryVersion {
   339	                version,
   340	                checksum: Some(ArtifactDigest::parse(&"d".repeat(64)).unwrap()),
   341	                yanked: Some(false),
   342	            },
   343	        ),
   344	        (
   345	            tag,
   346	            ProviderEvidenceV1::GitTag {
   347	                peeled_commit: revision,
   348	            },
   349	        ),
   350	    ] {
   351	        let observation = ProviderObservationV1::Exact { evidence };
   352	        state
   353	            .apply(
   354	                operation.id(),
   355	                &OperationEvent::ObservedExactBeforeEffect {
   356	                    evidence: observation.exact_evidence().unwrap(),
   357	                },
   358	            )
   359	            .unwrap();
   360	    }
   361	    ReleaseReceiptV1::from_state(&intent, &state).unwrap()
   362	}
