    pub package_dir: PathBuf,

    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub registry: Option<String>,

    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub tag: Option<String>,

    /// Explicit npm access level. When `None`, no `--access` flag is passed
