                .exact_evidence()
                .ok_or_else(|| ReleaseStateError::MissingEvidence {
                    id: Box::new(id.clone()),
                })?;
            check_evidence_role(id, proof.evidence())?;
            Some(proof.evidence().clone())
        } else {
